import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

const CreateViewSchema = z.object({
  name: z.string().min(1).max(100),
  filters: z.record(z.unknown()).default({}),
  sort: z.record(z.unknown()).optional(),
  columns: z.array(z.string()).optional(),
  scope: z.enum(['private', 'shared']).default('private'),
})

export async function GET(req: NextRequest) {
  try {
    const auth = await getAuthenticatedUser()
    if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const supabase = await createClient()
    const { data, error } = await supabase
      .from('client_views')
      .select('*')
      .eq('studio_id', auth.studioId)
      .or(`scope.eq.shared,created_by.eq.${auth.userId},is_system.eq.true`)
      .order('is_system', { ascending: false })
      .order('created_at', { ascending: true })

    if (error) {
      logger.error({ error }, 'Failed to fetch client views')
      return NextResponse.json({ error: 'Failed to fetch views' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'GET /api/client-views error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  try {
    const auth = await getAuthenticatedUser()
    if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const body: unknown = await req.json()
    const parsed = CreateViewSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json({ error: 'Invalid input', details: parsed.error.issues }, { status: 400 })
    }

    const supabase = await createClient()
    const { data, error } = await supabase
      .from('client_views')
      .insert({
        studio_id: auth.studioId,
        created_by: auth.userId,
        name: parsed.data.name,
        filters: parsed.data.filters,
        ...(parsed.data.sort !== undefined ? { sort: parsed.data.sort } : {}),
        ...(parsed.data.columns !== undefined ? { columns: parsed.data.columns } : {}),
        scope: parsed.data.scope,
        is_system: false,
      })
      .select()
      .single()

    if (error) {
      logger.error({ error }, 'Failed to create client view')
      return NextResponse.json({ error: 'Failed to create view' }, { status: 500 })
    }

    return NextResponse.json({ data }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'POST /api/client-views error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}
