import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

const UpdateViewSchema = z.object({
  name: z.string().min(1).max(100).optional(),
  filters: z.record(z.unknown()).optional(),
  sort: z.record(z.unknown()).nullable().optional(),
  columns: z.array(z.string()).nullable().optional(),
  scope: z.enum(['private', 'shared']).optional(),
})

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function PATCH(req: NextRequest, { params }: RouteContext) {
  try {
    const auth = await getAuthenticatedUser()
    if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const { id } = await params
    const body: unknown = await req.json()
    const parsed = UpdateViewSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json({ error: 'Invalid input', details: parsed.error.issues }, { status: 400 })
    }

    const supabase = await createClient()

    // Verify ownership or admin status
    const { data: existing, error: fetchErr } = await supabase
      .from('client_views')
      .select('id, created_by, scope, is_system, studio_id')
      .eq('id', id)
      .eq('studio_id', auth.studioId)
      .single()

    if (fetchErr || !existing) {
      return NextResponse.json({ error: 'View not found' }, { status: 404 })
    }
    if (existing.is_system) {
      return NextResponse.json({ error: 'System views cannot be modified' }, { status: 403 })
    }

    const updatePayload: Record<string, unknown> = {}
    if (parsed.data.name !== undefined) updatePayload['name'] = parsed.data.name
    if (parsed.data.filters !== undefined) updatePayload['filters'] = parsed.data.filters
    if (parsed.data.sort !== undefined) updatePayload['sort'] = parsed.data.sort
    if (parsed.data.columns !== undefined) updatePayload['columns'] = parsed.data.columns
    if (parsed.data.scope !== undefined) updatePayload['scope'] = parsed.data.scope

    const { data, error } = await supabase
      .from('client_views')
      .update(updatePayload)
      .eq('id', id)
      .select()
      .single()

    if (error) {
      logger.error({ error }, 'Failed to update client view')
      return NextResponse.json({ error: 'Failed to update view' }, { status: 500 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'PATCH /api/client-views/[id] error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function DELETE(_req: NextRequest, { params }: RouteContext) {
  try {
    const auth = await getAuthenticatedUser()
    if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const { id } = await params
    const supabase = await createClient()

    const { data: existing, error: fetchErr } = await supabase
      .from('client_views')
      .select('id, created_by, is_system, studio_id')
      .eq('id', id)
      .eq('studio_id', auth.studioId)
      .single()

    if (fetchErr || !existing) {
      return NextResponse.json({ error: 'View not found' }, { status: 404 })
    }
    if (existing.is_system) {
      return NextResponse.json({ error: 'System views cannot be deleted' }, { status: 403 })
    }

    const { error } = await supabase.from('client_views').delete().eq('id', id)
    if (error) {
      logger.error({ error }, 'Failed to delete client view')
      return NextResponse.json({ error: 'Failed to delete view' }, { status: 500 })
    }

    return new NextResponse(null, { status: 204 })
  } catch (err) {
    logger.error({ err }, 'DELETE /api/client-views/[id] error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}
