import { NextRequest, NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

interface RouteContext {
  params: Promise<{ id: string; photoId: string }>
}

export async function POST(_req: NextRequest, { params }: RouteContext) {
  try {
    const auth = await getAuthenticatedUser()
    if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

    const { id: clientId, photoId } = await params
    const supabase = await createClient()

    // Verify photo belongs to client + studio
    const { data: photo, error: photoErr } = await supabase
      .from('booking_photos')
      .select('id, storage_path')
      .eq('id', photoId)
      .eq('client_id', clientId)
      .eq('studio_id', auth.studioId)
      .single()

    if (photoErr || !photo) {
      return NextResponse.json({ error: 'Photo not found' }, { status: 404 })
    }

    // Create a signed URL with 30-day expiry (30 * 24 * 60 * 60 = 2592000 seconds)
    const { data: signedData, error: signErr } = await supabase.storage
      .from('client-photos')
      .createSignedUrl(photo.storage_path, 2592000)

    if (signErr || !signedData) {
      logger.error({ signErr }, 'Failed to create share link')
      return NextResponse.json({ error: 'Failed to create share link' }, { status: 500 })
    }

    const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()

    return NextResponse.json({
      shareToken: signedData.token,
      shareUrl: signedData.signedUrl,
      expiresAt,
    })
  } catch (err) {
    logger.error({ err }, 'POST /api/clients/[id]/photos/[photoId]/share error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}
