'use client'

import { useState, useEffect } from 'react'
import { toast } from 'sonner'
import { Loader2 } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import type { ClientView } from './SavedViewSwitcher'
import type { ClientFilters } from './ClientFilterBar'

interface SavedViewManagerProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  mode: 'create' | 'edit'
  view?: ClientView | null
  currentFilters: ClientFilters
  onSaved: (view: ClientView) => void
}

export function SavedViewManager({
  open,
  onOpenChange,
  mode,
  view,
  currentFilters,
  onSaved,
}: SavedViewManagerProps) {
  const [name, setName] = useState('')
  const [scope, setScope] = useState<'private' | 'shared'>('private')
  const [saving, setSaving] = useState(false)

  useEffect(() => {
    if (open) {
      setName(mode === 'edit' && view ? view.name : '')
      setScope(mode === 'edit' && view ? view.scope : 'private')
    }
  }, [open, mode, view])

  async function handleSave() {
    const trimmedName = name.trim()
    if (!trimmedName) return

    setSaving(true)
    try {
      const endpoint =
        mode === 'edit' && view
          ? `/api/client-views/${view.id}`
          : '/api/client-views'
      const method = mode === 'edit' ? 'PATCH' : 'POST'

      const payload =
        mode === 'create'
          ? { name: trimmedName, scope, filters: currentFilters }
          : { name: trimmedName, scope }

      const res = await fetch(endpoint, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to save view')
      }

      const json = await res.json() as { data: ClientView }
      toast.success(mode === 'create' ? 'View created' : 'View updated')
      onSaved(json.data)
      onOpenChange(false)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save view'
      toast.error(message)
    } finally {
      setSaving(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{mode === 'create' ? 'New view' : 'Edit view'}</DialogTitle>
          <DialogDescription>
            {mode === 'create'
              ? 'Save the current filters as a named view.'
              : 'Rename or change the visibility of this view.'}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="view-name">View name</Label>
            <Input
              id="view-name"
              autoFocus
              placeholder="e.g. VIP clients, Inactive this month…"
              value={name}
              onChange={(e) => setName(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter') void handleSave() }}
            />
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="view-scope">Visibility</Label>
            <Select value={scope} onValueChange={(v) => setScope(v as 'private' | 'shared')}>
              <SelectTrigger id="view-scope">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="private">Private — only you</SelectItem>
                <SelectItem value="shared">Shared — whole team</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={saving}>
            Cancel
          </Button>
          <Button onClick={() => void handleSave()} disabled={saving || !name.trim()}>
            {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {mode === 'create' ? 'Create view' : 'Save changes'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
