        </div>
      </div>

      {/* Active filter chips */}
      {hasActiveFilters && activeChips.length > 0 && (
        <div className="flex flex-wrap items-center gap-1.5">
          {activeChips.map((chip) => (
            <Badge
              key={chip.label}
