'use client'

import { useState, useCallback, useMemo } from 'react'
import Link from 'next/link'
import {
  Mail,
  MessageSquare,
  Phone,
  Check,
  Clock,
  AlertCircle,
  X,
  MessageCircle,
  CalendarCheck,
  FileCheck,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { EmptyState } from '@/components/shared/EmptyState'
import { CommDetailDrawer } from './CommDetailDrawer'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type Comm = Database['public']['Tables']['client_communications']['Row']

// Timeline event types
interface AppointmentEvent {
  type: 'appointment'
  id: string
  appointmentId: string
  serviceName: string | null
  artistName: string | null
  eventType: 'created' | 'confirmed' | 'completed' | 'cancelled' | 'no_show'
  occurredAt: string
}

interface ConsentEvent {
  type: 'consent'
  id: string
  submissionId: string
  templateName: string
  occurredAt: string
}

type TimelineEvent = AppointmentEvent | ConsentEvent

type FilterType = 'all' | 'email' | 'sms' | 'whatsapp' | 'events' | 'consent'

const CHANNEL_ICON: Record<Comm['channel'], React.ComponentType<{ className?: string }>> = {
  email: Mail,
  sms: MessageSquare,
  whatsapp: Phone,
  in_app: MessageSquare,
}

const CHANNEL_LABELS: Record<Comm['channel'], string> = {
  email: 'Email',
  sms: 'SMS',
  whatsapp: 'WhatsApp',
  in_app: 'In-App',
}

const STATUS_CONFIG: Record<
  Comm['status'],
  { label: string; dotClass: string; icon: React.ComponentType<{ className?: string }> }
> = {
  queued:    { label: 'Queued',    dotClass: 'bg-amber-500',   icon: Clock },
  sent:      { label: 'Sent',      dotClass: 'bg-blue-500',    icon: Check },
  delivered: { label: 'Delivered', dotClass: 'bg-emerald-500', icon: Check },
  opened:    { label: 'Opened',    dotClass: 'bg-emerald-500', icon: Check },
  clicked:   { label: 'Clicked',   dotClass: 'bg-primary',     icon: Check },
  failed:    { label: 'Failed',    dotClass: 'bg-destructive', icon: AlertCircle },
  bounced:   { label: 'Bounced',   dotClass: 'bg-destructive', icon: X },
}

const APPT_EVENT_LABELS: Record<AppointmentEvent['eventType'], string> = {
  created: 'Appointment created',
  confirmed: 'Appointment confirmed',
  completed: 'Appointment completed',
  cancelled: 'Appointment cancelled',
  no_show: 'No-show',
}

function formatRelativeOrDate(iso: string): string {
  const date = new Date(iso)
  const now = Date.now()
  const diff = now - date.getTime()
  const mins = Math.floor(diff / 60000)
  if (mins < 60) return `${Math.max(1, mins)}m ago`
  const hours = Math.floor(diff / 3600000)
  if (hours < 24) return `${hours}h ago`
  const days = Math.floor(diff / 86400000)
  if (days < 7) return `${days}d ago`
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
}

function getDayLabel(iso: string): string {
  const date = new Date(iso)
  const today = new Date()
  const yesterday = new Date(today)
  yesterday.setDate(today.getDate() - 1)

  if (date.toDateString() === today.toDateString()) return 'Today'
  if (date.toDateString() === yesterday.toDateString()) return 'Yesterday'
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
}

function groupByDay<T extends { occurredAt?: string; sent_at?: string | null; created_at: string }>(
  items: T[]
): Map<string, T[]> {
  const map = new Map<string, T[]>()
  for (const item of items) {
    const iso = ('occurredAt' in item ? item.occurredAt : item.sent_at ?? item.created_at) ?? item.created_at
    const label = getDayLabel(iso)
    const arr = map.get(label) ?? []
    arr.push(item)
    map.set(label, arr)
  }
  return map
}

interface CommRowProps {
  comm: Comm
  onClick: () => void
}

function CommRow({ comm, onClick }: CommRowProps) {
  const ChannelIcon = CHANNEL_ICON[comm.channel]
  const statusConf = STATUS_CONFIG[comm.status]

  return (
    <button
      type="button"
      role="listitem"
      className="w-full flex items-start gap-3 px-4 py-3 rounded-lg border border-border/40 bg-card hover:border-border/60 hover:bg-muted/30 transition-colors text-left"
      onClick={onClick}
    >
      <div className="mt-0.5 shrink-0 h-8 w-8 rounded-full bg-muted flex items-center justify-center">
        <ChannelIcon className={cn('h-4 w-4', `comm-dot-${comm.channel}`)} aria-hidden="true" />
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <span className="text-xs font-medium">{CHANNEL_LABELS[comm.channel]}</span>
          <span className="text-xs text-muted-foreground">·</span>
          <span className="text-xs text-muted-foreground capitalize">{comm.direction}</span>
        </div>
        {comm.subject && <p className="text-sm font-medium truncate mt-0.5">{comm.subject}</p>}
        <p className="text-sm text-muted-foreground truncate mt-0.5 leading-snug">{comm.body}</p>
      </div>
      <div className="flex flex-col items-end gap-1.5 shrink-0">
        <div className="flex items-center gap-1.5">
          <span className={cn('h-1.5 w-1.5 rounded-full', statusConf.dotClass)} />
          <span className="text-xs text-muted-foreground">{statusConf.label}</span>
        </div>
        <span className="text-[11px] text-muted-foreground tabular-nums">
          {formatRelativeOrDate(comm.sent_at ?? comm.created_at)}
        </span>
      </div>
    </button>
  )
}

function AppointmentEventRow({ event }: { event: AppointmentEvent }) {
  return (
    <div
      role="listitem"
      className="flex items-center gap-3 px-4 py-2.5 rounded-lg border border-border/30 bg-muted/20"
    >
      <CalendarCheck className="h-4 w-4 text-muted-foreground shrink-0" aria-hidden="true" />
      <div className="flex-1 min-w-0">
        <p className="text-sm">
          <span className="font-medium">{APPT_EVENT_LABELS[event.eventType]}</span>
          {' — '}
          <Link
            href={`/appointments/${event.appointmentId}`}
            className="text-primary hover:underline"
          >
            {event.serviceName ?? 'Appointment'}
          </Link>
        </p>
        <p className="text-xs text-muted-foreground">
          {[event.artistName, formatRelativeOrDate(event.occurredAt)].filter(Boolean).join(' · ')}
        </p>
      </div>
    </div>
  )
}

function ConsentEventRow({ event }: { event: ConsentEvent }) {
  return (
    <div
      role="listitem"
      className="flex items-center gap-3 px-4 py-2.5 rounded-lg border border-border/30 bg-muted/20"
    >
      <FileCheck className="h-4 w-4 text-muted-foreground shrink-0" aria-hidden="true" />
      <div className="flex-1 min-w-0">
        <p className="text-sm">
          Consent signed —{' '}
          <Link
            href={`/consent-forms/submissions/${event.submissionId}`}
            className="text-primary hover:underline"
          >
            {event.templateName}
          </Link>
        </p>
        <p className="text-xs text-muted-foreground">{formatRelativeOrDate(event.occurredAt)}</p>
      </div>
    </div>
  )
}

interface ClientTimelineCommsProps {
  clientId: string
  initialComms: Comm[]
  initialEvents?: TimelineEvent[]
}

export function ClientTimelineComms({
  clientId,
  initialComms,
  initialEvents = [],
}: ClientTimelineCommsProps) {
  const [comms, setComms] = useState<Comm[]>(initialComms)
  const [events] = useState<TimelineEvent[]>(initialEvents)
  const [loading, setLoading] = useState(false)
  const [activeFilter, setActiveFilter] = useState<FilterType>('all')
  const [selectedComm, setSelectedComm] = useState<Comm | null>(null)
  const [drawerOpen, setDrawerOpen] = useState(false)

  const refetch = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch(`/api/client-communications?client_id=${clientId}`)
      if (res.ok) {
        const json = await res.json() as { data: Comm[] }
        setComms(json.data ?? [])
      }
    } finally {
      setLoading(false)
    }
  }, [clientId])

  void refetch

  // Build a mixed timeline
  type MixedItem =
    | { kind: 'comm'; data: Comm; sortKey: string }
    | { kind: 'event'; data: TimelineEvent; sortKey: string }

  const allItems = useMemo<MixedItem[]>(() => {
    const commItems: MixedItem[] = comms
      .filter((c) => {
        if (activeFilter === 'all') return true
        if (activeFilter === 'events' || activeFilter === 'consent') return false
        return c.channel === activeFilter
      })
      .map((c): MixedItem => ({
        kind: 'comm',
        data: c,
        sortKey: c.sent_at ?? c.created_at,
      }))

    const eventItems: MixedItem[] = events
      .filter((e) => {
        if (activeFilter === 'all') return true
        if (activeFilter === 'events') return e.type === 'appointment'
        if (activeFilter === 'consent') return e.type === 'consent'
        return false
      })
      .map((e): MixedItem => ({
        kind: 'event',
        data: e,
        sortKey: e.occurredAt,
      }))

    return [...commItems, ...eventItems].sort((a, b) =>
      b.sortKey.localeCompare(a.sortKey)
    )
  }, [comms, events, activeFilter])

  // Group by day
  const grouped = useMemo(() => {
    const map = new Map<string, MixedItem[]>()
    for (const item of allItems) {
      const label = getDayLabel(item.sortKey)
      const arr = map.get(label) ?? []
      arr.push(item)
      map.set(label, arr)
    }
    return map
  }, [allItems])

  const FILTER_CHIPS: { value: FilterType; label: string }[] = [
    { value: 'all', label: 'All' },
    { value: 'email', label: 'Email' },
    { value: 'sms', label: 'SMS' },
    { value: 'whatsapp', label: 'WhatsApp' },
    { value: 'events', label: 'Events' },
    { value: 'consent', label: 'Consent' },
  ]

  return (
    <div className="flex flex-col gap-4">
      {/* Type filter chips */}
      <div className="flex items-center gap-1.5 flex-wrap">
        {FILTER_CHIPS.map((chip) => (
          <Button
            key={chip.value}
            size="sm"
            variant="outline"
            className={cn(
              'h-7 text-xs rounded-full',
              activeFilter === chip.value && 'bg-primary/10 border-primary/30 text-primary'
            )}
            onClick={() => setActiveFilter(chip.value)}
          >
            {chip.label}
          </Button>
        ))}
      </div>

      {/* Feed */}
      {loading ? (
        <div className="space-y-2">
          {[1, 2, 3, 4].map((i) => (
            <Skeleton key={i} className="h-14 w-full rounded-lg" />
          ))}
        </div>
      ) : allItems.length === 0 ? (
        <EmptyState
          icon={MessageCircle}
          title="No activity yet"
          description="All messages, appointment events, and consent submissions will appear here."
          variant="first-time"
        />
      ) : (
        <div className="space-y-2">
          {Array.from(grouped.entries()).map(([label, items]) => (
            <section
              key={label}
              aria-label={label}
              className="motion-safe:animate-in motion-safe:fade-in-0 motion-safe:duration-200"
            >
              <div className="flex items-center gap-3 my-4">
                <div className="h-px flex-1 bg-border/40" aria-hidden="true" />
                <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wide px-1">
                  {label}
                </span>
                <div className="h-px flex-1 bg-border/40" aria-hidden="true" />
              </div>
              <div className="space-y-2">
                {items.map((item) => {
                  if (item.kind === 'comm') {
                    return (
                      <CommRow
                        key={`comm-${item.data.id}`}
                        comm={item.data}
                        onClick={() => {
                          setSelectedComm(item.data)
                          setDrawerOpen(true)
                        }}
                      />
                    )
                  }
                  if (item.data.type === 'appointment') {
                    return (
                      <AppointmentEventRow
                        key={`appt-${item.data.id}`}
                        event={item.data}
                      />
                    )
                  }
                  return (
                    <ConsentEventRow
                      key={`consent-${item.data.id}`}
                      event={item.data}
                    />
                  )
                })}
              </div>
            </section>
          ))}
        </div>
      )}

      <CommDetailDrawer
        comm={selectedComm}
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
      />
    </div>
  )
}
