import type { Database } from '@/lib/supabase/types'

type NoteCategory = Database['public']['Tables']['client_notes']['Row']['category']

const CATEGORIES: { value: NoteCategory; label: string; dotClass: string }[] = [
  { value: 'general', label: 'General', dotClass: 'note-dot-general' },
  { value: 'medical', label: 'Medical', dotClass: 'note-dot-medical' },
  { value: 'allergies', label: 'Allergies', dotClass: 'note-dot-allergies' },
  { value: 'skin', label: 'Skin type', dotClass: 'note-dot-skin' },
  { value: 'emergency_contact', label: 'Emergency contact', dotClass: 'note-dot-emergency_contact' },
  { value: 'aftercare', label: 'Aftercare', dotClass: 'note-dot-aftercare' },
  { value: 'preferences', label: 'Preferences', dotClass: 'note-dot-preferences' },
  { value: 'artist_notes', label: 'Artist notes', dotClass: 'note-dot-artist_notes' },
]

interface Artist {
  id: string
  display_name: string
}

interface RecentAppointment {
  id: string
  scheduled_at: string
  services?: { name: string } | null
}

interface AddNoteModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  clientId: string
  artists?: Artist[]
  recentAppointments?: RecentAppointment[]
  onSuccess?: () => void
}

export function AddNoteModal({
  open,
  onOpenChange,
  clientId,
  artists = [],
  recentAppointments = [],
  onSuccess,
}: AddNoteModalProps) {
  const [category, setCategory] = useState<NoteCategory>('general')
  const [isPinned, setIsPinned] = useState(false)
  const [linkedAppointmentId, setLinkedAppointmentId] = useState<string>('')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const editor = useEditor({
    extensions: [
      StarterKit,
      Mention.configure({
        HTMLAttributes: { class: 'note-mention' },
        suggestion: {
          items: ({ query }: { query: string }) =>
            artists
              .filter((a) => a.display_name.toLowerCase().includes(query.toLowerCase()))
              .slice(0, 5),
          render: () => {
            // Simple mention render — suggestion list appears inline below cursor
            return {
              onStart: () => undefined,
              onUpdate: () => undefined,
              onKeyDown: () => false,
              onExit: () => undefined,
            }
          },
        },
      }),
    ],
    editorProps: {
      attributes: {
        class: 'prose prose-sm dark:prose-invert max-w-none focus:outline-none min-h-[120px] px-3 py-2',
        'aria-label': 'Note content',
      },
    },
  })

  // Reset on close
  useEffect(() => {
    if (!open && editor) {
      editor.commands.clearContent()
      setCategory('general')
      setIsPinned(false)
      setLinkedAppointmentId('')
      setError(null)
    }
  }, [open, editor])

  async function handleSave() {
    if (!editor) return
    const body = editor.getText().trim()
    if (body.length < 2) {
      setError('Note must be at least 2 characters.')
      return
    }
    const htmlContent = editor.getHTML()
    setSaving(true)
    setError(null)
    try {
      const res = await fetch('/api/client-notes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_id: clientId,
          category,
          body: htmlContent,
          is_pinned: isPinned,
          ...(linkedAppointmentId ? { appointment_id: linkedAppointmentId } : {}),
        }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to save note')
      }
      toast.success('Note saved')
      editor.commands.clearContent()
      setCategory('general')
      setIsPinned(false)
      setLinkedAppointmentId('')
      onOpenChange(false)
      onSuccess?.()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save note'
      toast.error(message)
      setError(message)
    } finally {
      setSaving(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[520px]">
        <DialogHeader>
          <DialogTitle>Add note</DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="note-category">Category</Label>
            <Select value={category} onValueChange={(v) => setCategory(v as NoteCategory)}>
              <SelectTrigger id="note-category">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {CATEGORIES.map((c) => (
                  <SelectItem key={c.value} value={c.value}>
                    <span className="flex items-center gap-2">
                      <span className={cn('h-2 w-2 rounded-full', c.dotClass)} />
                      {c.label}
                    </span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Tiptap editor */}
          <div className="space-y-1.5">
            <Label>Note</Label>
            {/* Toolbar */}
            <div className="flex items-center gap-0.5 px-1 py-1 border border-input rounded-t-md bg-muted/30">
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className={cn(
                  'h-7 w-7',
                  editor?.isActive('bold') && 'bg-muted'
                )}
                onClick={() => editor?.chain().focus().toggleBold().run()}
                aria-label="Bold"
                aria-pressed={editor?.isActive('bold') ?? false}
              >
                <Bold className="h-3.5 w-3.5" aria-hidden="true" />
              </Button>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className={cn(
                  'h-7 w-7',
                  editor?.isActive('italic') && 'bg-muted'
                )}
                onClick={() => editor?.chain().focus().toggleItalic().run()}
                aria-label="Italic"
                aria-pressed={editor?.isActive('italic') ?? false}
              >
                <Italic className="h-3.5 w-3.5" aria-hidden="true" />
              </Button>
              <Separator orientation="vertical" className="h-5 mx-1" />
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className={cn(
                  'h-7 w-7',
                  editor?.isActive('bulletList') && 'bg-muted'
                )}
                onClick={() => editor?.chain().focus().toggleBulletList().run()}
                aria-label="Bullet list"
                aria-pressed={editor?.isActive('bulletList') ?? false}
              >
                <List className="h-3.5 w-3.5" aria-hidden="true" />
              </Button>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="h-7 w-7"
                onClick={() => editor?.chain().focus().setHorizontalRule().run()}
                aria-label="Divider"
              >
                <Minus className="h-3.5 w-3.5" aria-hidden="true" />
              </Button>
              {artists.length > 0 && (
                <>
                  <Separator orientation="vertical" className="h-5 mx-1" />
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7"
                    onClick={() => editor?.chain().focus().insertContent('@').run()}
                    aria-label="Mention artist"
                  >
                    <AtSign className="h-3.5 w-3.5" aria-hidden="true" />
                  </Button>
                </>
              )}
            </div>
            <div
              className={cn(
                'rounded-b-md border border-t-0 border-input bg-background text-sm ring-offset-background',
                'focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2'
              )}
            >
              <EditorContent editor={editor} />
            </div>
            {error && (
              <p role="alert" className="text-xs text-destructive">{error}</p>
            )}
          </div>

          {/* Link to appointment */}
          {recentAppointments.length > 0 && (
            <div className="space-y-1.5">
              <Label htmlFor="link-appointment">Link to appointment (optional)</Label>
              <Select
                value={linkedAppointmentId}
                onValueChange={setLinkedAppointmentId}
              >
                <SelectTrigger id="link-appointment" className="h-9">
                  <SelectValue placeholder="Select appointment…" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">None</SelectItem>
                  {recentAppointments.map((appt) => (
                    <SelectItem key={appt.id} value={appt.id}>
                      {new Date(appt.scheduled_at).toLocaleDateString('en-US', {
                        month: 'short',
                        day: 'numeric',
                        year: 'numeric',
                      })}{' '}
                      — {appt.services?.name ?? 'Session'}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          <div className="flex items-center gap-2">
            <Checkbox
              id="pin-note"
              checked={isPinned}
              onCheckedChange={(v) => setIsPinned(Boolean(v))}
            />
            <Label htmlFor="pin-note" className="text-sm cursor-pointer">
              Pin to overview
            </Label>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={saving}>
            Cancel
          </Button>
          <Button onClick={() => void handleSave()} disabled={saving}>
            {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Save note
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
