'use client'

import { useEffect, useState, useCallback, useRef } from 'react'
import { X, ChevronLeft, ChevronRight, Download, FolderDown, Share2, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { Dialog, DialogContent } from '@/components/ui/dialog'
import { cn } from '@/lib/utils'

export interface LightboxPhoto {
  id: string
  storagePath: string
  kind: string
  bookingDate?: string
  serviceName?: string
  artistName?: string
  caption?: string | null
}

interface PhotoLightboxProps {
  photos: LightboxPhoto[]
  initialIndex: number
  open: boolean
  onOpenChange: (open: boolean) => void
  getSignedUrl: (storagePath: string) => Promise<string>
  clientId?: string
}

const SWIPE_THRESHOLD = 50

export function PhotoLightbox({
  photos,
  initialIndex,
  open,
  onOpenChange,
  getSignedUrl,
  clientId,
}: PhotoLightboxProps) {
  const [index, setIndex] = useState(initialIndex)
  const [url, setUrl] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)
  const [bulkDownloading, setBulkDownloading] = useState(false)
  const [sharing, setSharing] = useState(false)

  const pointerStartX = useRef<number | null>(null)

  const current = photos[index]

  const loadPhoto = useCallback(async (path: string) => {
    setLoading(true)
    setUrl(null)
    try {
      const signed = await getSignedUrl(path)
      setUrl(signed)
    } catch {
      toast.error('Failed to load photo')
    } finally {
      setLoading(false)
    }
  }, [getSignedUrl])

  useEffect(() => {
    if (open && current) {
      setIndex(initialIndex)
      void loadPhoto(current.storagePath)
    }
  }, [open, initialIndex]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (open && current) {
      void loadPhoto(current.storagePath)
    }
  }, [index, open, current, loadPhoto])

  const goNext = useCallback(() => {
    setIndex((i) => (i + 1) % photos.length)
  }, [photos.length])

  const goPrev = useCallback(() => {
    setIndex((i) => (i - 1 + photos.length) % photos.length)
  }, [photos.length])

  // Keyboard navigation
  useEffect(() => {
    if (!open) return

    function handleKey(e: KeyboardEvent) {
      if (e.key === 'ArrowRight') goNext()
      else if (e.key === 'ArrowLeft') goPrev()
      else if (e.key === 'd' || e.key === 'D') handleDownload()
      else if (e.key === 'f' || e.key === 'F') {
        void document.documentElement.requestFullscreen?.()
      }
    }

    window.addEventListener('keydown', handleKey)
    return () => window.removeEventListener('keydown', handleKey)
  }, [open, goNext, goPrev]) // eslint-disable-line react-hooks/exhaustive-deps

  function handleDownload() {
    if (!url || !current) return
    const a = document.createElement('a')
    a.href = url
    a.download = `photo-${current.id}.jpg`
    a.click()
  }

  async function handleBulkDownload() {
    if (!clientId) {
      toast.error('Client ID required for bulk download')
      return
    }
    setBulkDownloading(true)
    try {
      const res = await fetch(`/api/clients/${clientId}/photos/bulk-download`, { method: 'POST' })
      if (!res.ok) throw new Error('Failed to start download')
      toast.info('Preparing download… You will receive an email with the download link.')
    } catch {
      toast.error('Failed to start download')
    } finally {
      setBulkDownloading(false)
    }
  }

  async function handleShare() {
    if (!current || !clientId) return
    setSharing(true)
    try {
      const res = await fetch(`/api/clients/${clientId}/photos/${current.id}/share`, { method: 'POST' })
      if (!res.ok) throw new Error('Failed to create share link')
      const json = await res.json() as { shareUrl: string }
      await navigator.clipboard.writeText(json.shareUrl)
      toast.success('Link copied · expires in 30 days')
    } catch {
      toast.error('Failed to create share link')
    } finally {
      setSharing(false)
    }
  }

  if (!current) return null

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="lightbox-overlay max-w-none w-screen h-screen p-0 rounded-none border-0 flex flex-col items-center justify-center"
        aria-label={`Photo ${index + 1} of ${photos.length}`}
        onPointerDown={(e) => { pointerStartX.current = e.clientX }}
        onPointerUp={(e) => {
          if (pointerStartX.current === null) return
          const delta = e.clientX - pointerStartX.current
          if (delta < -SWIPE_THRESHOLD) goNext()
          else if (delta > SWIPE_THRESHOLD) goPrev()
          pointerStartX.current = null
        }}
      >
        {/* Close button */}
        <Button
          variant="ghost"
          size="icon"
          className="absolute top-4 right-4 h-9 w-9 text-white/70 hover:text-white hover:bg-white/10 z-50"
          onClick={() => onOpenChange(false)}
          aria-label="Close lightbox"
        >
          <X className="h-5 w-5" aria-hidden="true" />
        </Button>

        {/* Counter */}
        <div className="absolute top-4 left-1/2 -translate-x-1/2 text-xs text-white/60 tabular-nums z-50">
          {index + 1} / {photos.length}
        </div>

        {/* Prev */}
        {photos.length > 1 && (
          <Button
            variant="ghost"
            size="icon"
            className="absolute left-4 top-1/2 -translate-y-1/2 h-12 w-12 text-white/70 hover:text-white hover:bg-white/10 z-50"
            onClick={goPrev}
            aria-label="Previous photo"
          >
            <ChevronLeft className="h-6 w-6" aria-hidden="true" />
          </Button>
        )}

        {/* Photo */}
        <div className="flex-1 flex items-center justify-center w-full px-20 py-16">
          {loading && <Skeleton className="max-h-[85vh] max-w-[85vw] w-[600px] h-[400px]" />}
          {url && !loading && (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={url}
              alt={current.caption ?? `Photo (${current.kind})`}
              className={cn(
                'max-h-[85vh] max-w-[85vw] object-contain mx-auto rounded-md',
                'touch-pan-y'
              )}
              draggable={false}
            />
          )}
        </div>

        {/* Next */}
        {photos.length > 1 && (
          <Button
            variant="ghost"
            size="icon"
            className="absolute right-4 top-1/2 -translate-y-1/2 h-12 w-12 text-white/70 hover:text-white hover:bg-white/10 z-50"
            onClick={goNext}
            aria-label="Next photo"
          >
            <ChevronRight className="h-6 w-6" aria-hidden="true" />
          </Button>
        )}

        {/* Meta strip */}
        <div className="absolute bottom-0 left-0 right-0 bg-background/80 backdrop-blur-sm flex items-center justify-between px-6 py-3 gap-4">
          <span className="text-sm text-muted-foreground truncate">
            {[current.bookingDate, current.serviceName, current.artistName, current.kind]
              .filter(Boolean)
              .join(' · ')}
          </span>
          <div className="flex gap-1 shrink-0">
            {clientId && (
              <Button
                variant="ghost"
                size="sm"
                className="text-muted-foreground hover:text-foreground"
                onClick={handleShare}
                disabled={sharing}
                aria-label="Share photo"
              >
                {sharing
                  ? <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />
                  : <Share2 className="mr-2 h-4 w-4" aria-hidden="true" />
                }
                Share
              </Button>
            )}
            <Button
              variant="ghost"
              size="sm"
              className="text-muted-foreground hover:text-foreground"
              onClick={handleDownload}
              aria-label="Download this photo"
            >
              <Download className="mr-2 h-4 w-4" aria-hidden="true" />
              Download
            </Button>
            {clientId && photos.length > 1 && (
              <Button
                variant="ghost"
                size="sm"
                className="text-muted-foreground hover:text-foreground"
                onClick={() => void handleBulkDownload()}
                disabled={bulkDownloading}
                aria-label={`Download all ${photos.length} photos`}
              >
                {bulkDownloading
                  ? <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />
                  : <FolderDown className="mr-2 h-4 w-4" aria-hidden="true" />
                }
                All ({photos.length})
              </Button>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}
