import { TableSkeleton } from '@/components/skeletons'
import { Alert, AlertDescription } from '@/components/ui/alert'
import type { ClientTag } from '@/components/clients/TagChip'
import type { Database } from '@/lib/supabase/types'

type Client = Database['public']['Tables']['clients']['Row']

interface ClientsPageClientProps {
  initialClients: Client[]
  tagLibrary: ClientTag[]
}

const DEFAULT_FILTERS: ClientFilters = {
  q: '',
  tags: [],
  vip: false,
  inactive: false,
  noShows: false,
  showArchived: false,
  spendingTier: '',
  artistIds: [],
  serviceIds: [],
  lastVisitRange: '',
}

export function ClientsPageClient({ initialClients, tagLibrary }: ClientsPageClientProps) {
  const router = useRouter()
  const searchParams = useSearchParams()

  const [clients, setClients] = useState<Client[]>(initialClients)
  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [loading, setLoading] = useState(false)
  const [fetchError, setFetchError] = useState<Error | null>(null)
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [editingClient, setEditingClient] = useState<Client | null>(null)
  const [noteClientId, setNoteClientId] = useState<string | null>(null)
  const [page, setPage] = useState(1)
  const [hasMore, setHasMore] = useState(false)
  const [totalCount, setTotalCount] = useState<number | null>(null)

  // Saved views
  const [views, setViews] = useState<ClientView[]>([])
  const [activeViewId, setActiveViewId] = useState<string | null>(null)
  const [viewManagerOpen, setViewManagerOpen] = useState(false)
  const [viewManagerMode, setViewManagerMode] = useState<'create' | 'edit'>('create')
  const [editingView, setEditingView] = useState<ClientView | null>(null)
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)

  // Load saved views on mount
  useEffect(() => {
    void fetchViews()
  }, [])

  async function fetchViews() {
    try {
      const res = await fetch('/api/client-views')
      if (res.ok) {
        const json = await res.json() as { data: ClientView[] }
        setViews(json.data ?? [])
        // Auto-activate first system default view
        const defaultView = json.data?.find((v) => v.is_default)
        if (defaultView && !activeViewId) {
          setActiveViewId(defaultView.id)
        }
      }
    } catch {
      toast.error('Failed to load views', { description: 'Using All clients as default' })
    }
  }

  // Restore page from URL
  useEffect(() => {
    const p = parseInt(searchParams.get('page') ?? '1', 10)
    if (p > 1) {
      setPage(p)
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const fetchClients = useCallback(async (f: ClientFilters, p = 1) => {
    setLoading(true)
    setFetchError(null)
    try {
      const params = new URLSearchParams()
      if (f.q) params.set('q', f.q)
      if (f.tags.length) params.set('tags', f.tags.join(','))
      if (f.vip) params.set('vip', 'true')
      if (f.inactive) params.set('inactive', 'true')
      if (f.noShows) params.set('no_show', 'true')
      if (!f.showArchived) params.set('archived', 'false')
      else params.set('archived', 'any')
      if (f.spendingTier) params.set('spending', f.spendingTier)
      if (f.artistIds.length) params.set('artist_ids', f.artistIds.join(','))
      if (f.serviceIds.length) params.set('service_ids', f.serviceIds.join(','))
      if (f.lastVisitRange) params.set('last_visit_range', f.lastVisitRange)
      params.set('page', String(p))
      params.set('per_page', '50')

      const res = await fetch(`/api/clients?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to load clients')
      const json = await res.json() as { data: Client[]; count: number }

      if (p === 1) {
        setClients(json.data ?? [])
      } else {
        setClients((prev) => [...prev, ...(json.data ?? [])])
      }
      setTotalCount(json.count ?? null)
      setHasMore((json.data?.length ?? 0) >= 50)
    } catch (err) {
      setFetchError(err instanceof Error ? err : new Error('Failed to load clients'))
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    void fetchClients(filters, 1)
    setPage(1)
    setSelectedIds([])
  }, [filters, fetchClients])

  function handleFiltersChange(f: ClientFilters) {
    setFilters(f)
    setHasUnsavedChanges(true)
  }

  function handleViewChange(viewId: string | null) {
    setActiveViewId(viewId)
    setHasUnsavedChanges(false)
    const view = views.find((v) => v.id === viewId)
    if (view) {
      // Apply view filters
      const viewFilters = view.filters as Partial<ClientFilters>
      setFilters({ ...DEFAULT_FILTERS, ...viewFilters })
    } else {
      setFilters(DEFAULT_FILTERS)
    }
  }

  async function handleDeleteView(viewId: string) {
    try {
      const res = await fetch(`/api/client-views/${viewId}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to delete view')
      setViews((prev) => prev.filter((v) => v.id !== viewId))
      if (activeViewId === viewId) {
        const defaultView = views.find((v) => v.is_default)
        setActiveViewId(defaultView?.id ?? null)
      }
      toast.success('View deleted')
    } catch {
      toast.error('Failed to delete view')
    }
  }

  async function handleDuplicateView(view: ClientView) {
    try {
      const res = await fetch('/api/client-views', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: `${view.name} (copy)`,
          filters: view.filters,
          scope: 'private',
        }),
      })
      if (!res.ok) throw new Error('Failed to duplicate view')
      const json = await res.json() as { data: ClientView }
      setViews((prev) => [...prev, json.data])
      toast.success('View duplicated')
    } catch {
      toast.error('Failed to duplicate view')
    }
  }

  function handleViewSaved(savedView: ClientView) {
    setViews((prev) => {
      const idx = prev.findIndex((v) => v.id === savedView.id)
      if (idx >= 0) {
        const next = [...prev]
        next[idx] = savedView
        return next
      }
      return [...prev, savedView]
    })
    setActiveViewId(savedView.id)
    setHasUnsavedChanges(false)
  }

  function handleLoadMore() {
    const nextPage = page + 1
    setPage(nextPage)
    router.replace(`?page=${nextPage}`, { scroll: false })
    void fetchClients(filters, nextPage)
  }

  function handleEditClient(client: Client) {
    setEditingClient(client)
    setDrawerOpen(true)
  }

  function handleNewClient() {
    setEditingClient(null)
    setDrawerOpen(true)
  }

  function handleDrawerSuccess(client: Client) {
    setClients((prev) => {
      const idx = prev.findIndex((c) => c.id === client.id)
      if (idx >= 0) {
        const next = [...prev]
        next[idx] = client
        return next
      }
      return [client, ...prev]
    })
  }

  const hasActiveFilters = !!(
    filters.q || filters.tags.length > 0 || filters.vip ||
    filters.inactive || filters.noShows || filters.spendingTier ||
    filters.artistIds.length > 0 || filters.serviceIds.length > 0 || filters.lastVisitRange
  )

  const inactiveCount = useMemo(() => {
    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000
    return clients.filter(
      (c) => !c.archived_at && c.last_visit_at !== null && new Date(c.last_visit_at).getTime() < cutoff
    ).length
  }, [clients])

  const activeView = views.find((v) => v.id === activeViewId) ?? null
  const isInitialLoad = loading && clients.length === 0

  return (
    <div className="flex flex-col gap-4 p-4 lg:p-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div>
            <Typography variant="h1">Clients</Typography>
            <p className="text-sm text-muted-foreground mt-0.5">
              {totalCount !== null ? (
                <span className="tabular-nums">
                  {clients.length} of {totalCount} client{totalCount !== 1 ? 's' : ''}
                </span>
              ) : clients.length > 0 ? (
                <span className="tabular-nums">{clients.length} client{clients.length !== 1 ? 's' : ''}</span>
              ) : null}
            </p>
          </div>
          {inactiveCount > 0 && (
            <span
              title={`${inactiveCount} client${inactiveCount !== 1 ? 's' : ''} not seen in 90+ days`}
              className="inline-flex items-center gap-1 rounded-full bg-destructive/10 text-destructive text-xs font-medium px-2 py-0.5 select-none"
            >
              <span className="h-2 w-2 rounded-full bg-destructive shrink-0" aria-hidden="true" />
              {inactiveCount} inactive
            </span>
          )}
        </div>
        <Button onClick={handleNewClient}>
          <Plus className="mr-2 h-4 w-4" aria-hidden="true" />
          New client
        </Button>
      </div>

      {/* Saved views switcher */}
      {views.length > 0 && (
        <SavedViewSwitcher
          views={views}
          activeViewId={activeViewId}
          onViewChange={handleViewChange}
          onCreateView={() => {
            setViewManagerMode('create')
            setEditingView(null)
            setViewManagerOpen(true)
          }}
          onEditView={(view) => {
            setViewManagerMode('edit')
            setEditingView(view)
            setViewManagerOpen(true)
          }}
          onDuplicateView={handleDuplicateView}
          onDeleteView={handleDeleteView}
        />
      )}

      {/* Unsaved changes banner */}
      {hasUnsavedChanges && activeView && !activeView.is_system && (
        <Alert className="py-2 border-amber-500/30 bg-amber-500/5">
          <AlertDescription className="flex items-center justify-between gap-3 text-xs">
            <span className="text-amber-700 dark:text-amber-400">
              Unsaved changes. Save view or discard?
            </span>
            <div className="flex gap-2 shrink-0">
              <Button
                size="sm"
                variant="outline"
                className="h-6 text-xs px-2"
                onClick={() => {
                  setFilters({ ...DEFAULT_FILTERS, ...(activeView.filters as Partial<ClientFilters>) })
                  setHasUnsavedChanges(false)
                }}
              >
                Discard
              </Button>
              <Button
                size="sm"
                className="h-6 text-xs px-2"
                onClick={() => {
                  setViewManagerMode('edit')
                  setEditingView(activeView)
                  setViewManagerOpen(true)
                }}
              >
                Save view
              </Button>
            </div>
          </AlertDescription>
        </Alert>
      )}

      <ClientFilterBar
        filters={filters}
        onChange={handleFiltersChange}
        tagLibrary={tagLibrary}
      />

      {selectedIds.length > 0 && (
        <BulkActionsBar
          selectedIds={selectedIds}
          tagLibrary={tagLibrary}
          onClearSelection={() => setSelectedIds([])}
          onArchived={() => void fetchClients(filters, 1)}
          onTagsApplied={() => void fetchClients(filters, 1)}
        />
      )}

      <DataState
        data={clients}
        isLoading={isInitialLoad}
        isError={!!fetchError && clients.length === 0}
        error={fetchError}
        loadingSlot={<TableSkeleton rows={8} />}
        emptySlot={
          hasActiveFilters ? (
            <EmptyState
              icon={SearchX}
              title="No clients match these filters"
              description="Try different filters or clear all to see everyone."
              cta={{ label: 'Clear filters', onClick: () => { setFilters(DEFAULT_FILTERS); setHasUnsavedChanges(false) } }}
              variant="no-results"
            />
          ) : activeView && activeViewId ? (
            <EmptyState
              icon={BookmarkX}
              title="No clients in this view"
              description={`The filters in "${activeView.name}" returned no results.`}
              cta={{
                label: 'Edit view filters',
                onClick: () => {
                  setViewManagerMode('edit')
                  setEditingView(activeView)
                  setViewManagerOpen(true)
                },
              }}
              variant="no-results"
            />
          ) : (
            <EmptyState
              icon={Users}
              title="No clients yet"
              description="Add your first client or import from CSV — they'll show up here as they book."
              cta={{ label: '+ Add client', onClick: handleNewClient }}
              variant="first-time"
            />
          )
        }
        errorSlot={
          <PageError
            error={fetchError ?? new Error('Failed to load clients')}
            reset={() => void fetchClients(filters, 1)}
            variant="inline"
          />
        }
      >
        {(data) => (
          <ClientsTable
            clients={data}
            tagLibrary={tagLibrary}
            loading={loading && data.length === 0}
            selectedIds={selectedIds}
            onSelectionChange={setSelectedIds}
            onEdit={handleEditClient}
            onAddNote={(id) => setNoteClientId(id)}
          />
        )}
      </DataState>

      {/* Load more */}
      {(hasMore || loading) && clients.length > 0 && (
        <div className="flex items-center justify-between py-4">
          <span className="text-sm text-muted-foreground tabular-nums">
            Showing {clients.length}{totalCount !== null ? ` of ${totalCount}` : ''} clients
          </span>
          {hasMore && (
            <Button variant="outline" size="sm" onClick={handleLoadMore} disabled={loading}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />}
              Load more
            </Button>
          )}
        </div>
      )}

      <ClientDrawer
        open={drawerOpen}
        onOpenChange={(v) => {
          setDrawerOpen(v)
          if (!v) setEditingClient(null)
        }}
        client={editingClient}
        tagLibrary={tagLibrary}
        onSuccess={handleDrawerSuccess}
      />

      {noteClientId && (
        <AddNoteModal
          open={Boolean(noteClientId)}
          onOpenChange={(v) => { if (!v) setNoteClientId(null) }}
          clientId={noteClientId}
        />
      )}

      <SavedViewManager
        open={viewManagerOpen}
        onOpenChange={setViewManagerOpen}
        mode={viewManagerMode}
        view={editingView}
        currentFilters={filters}
        onSaved={handleViewSaved}
      />
    </div>
  )
}
